import React, { useState } from "react";

export default function Settings() {

  const [name, setName] = useState("");

  const [email, setEmail] = useState("");

  const [password, setPassword] = useState("");

  const [darkMode, setDarkMode] = useState(false);

  const [notification, setNotification] = useState(true);


  const saveSettings = () => {

    alert("Settings Saved Successfully ✅");

  };


  return (

    <div

      style={{

        minHeight: "100vh",

        background:

          "linear-gradient(135deg,#0f172a,#1e293b,#334155)",

        padding: "40px"

      }}

    >

      <h1

        style={{

          textAlign: "center",

          color: "white",

          fontSize: "45px",

          marginBottom: "10px"

        }}

      >

        ⚙️ Settings

      </h1>


      <p

        style={{

          textAlign: "center",

          color: "#cbd5e1",

          marginBottom: "40px"

        }}

      >

        Manage your account settings

      </p>




      <div

        style={{

          background: "white",

          maxWidth: "700px",

          margin: "auto",

          padding: "35px",

          borderRadius: "25px",

          boxShadow:

            "0 15px 35px rgba(0,0,0,0.3)"

        }}

      >

        <h2

          style={{

            color: "#2563eb",

            marginBottom: "25px"

          }}

        >

          👤 Profile Settings

        </h2>


        <input

          type="text"

          placeholder="Enter Full Name"

          value={name}

          onChange={(e)=>

          setName(e.target.value)

          }

          style={inputStyle}

        />


        <input

          type="email"

          placeholder="Enter Email"

          value={email}

          onChange={(e)=>

          setEmail(e.target.value)

          }

          style={inputStyle}

        />



        <input

          type="password"

          placeholder="Change Password"

          value={password}

          onChange={(e)=>

          setPassword(e.target.value)

          }

          style={inputStyle}

        />




        <div style={optionBox}>

          <span>

            🌙 Dark Mode

          </span>


          <button

            onClick={()=>

            setDarkMode(!darkMode)

            }

            style={

            darkMode

            ?

            activeBtn

            :

            inactiveBtn

            }

          >

            {

            darkMode

            ?

            "ON"

            :

            "OFF"

            }

          </button>

        </div>





        <div style={optionBox}>

          <span>

            🔔 Notifications

          </span>


          <button

            onClick={()=>

            setNotification(

            !notification

            )

            }

            style={

            notification

            ?

            activeBtn

            :

            inactiveBtn

            }

          >

            {

            notification

            ?

            "ON"

            :

            "OFF"

            }

          </button>

        </div>





        <button

          onClick={saveSettings}

          style={saveBtn}

        >

          Save Settings

        </button>

      </div>

    </div>

  );

}



const inputStyle = {

  width: "100%",

  padding: "14px",

  marginBottom: "20px",

  borderRadius: "12px",

  border: "1px solid #cbd5e1",

  outline: "none",

  fontSize: "15px"

};



const optionBox = {

  display: "flex",

  justifyContent: "space-between",

  alignItems: "center",

  marginBottom: "25px",

  fontSize: "18px",

  fontWeight: "bold"

};



const activeBtn = {

  background: "#22c55e",

  color: "white",

  border: "none",

  padding: "10px 20px",

  borderRadius: "25px",

  cursor: "pointer",

  fontWeight: "bold"

};



const inactiveBtn = {

  background: "#ef4444",

  color: "white",

  border: "none",

  padding: "10px 20px",

  borderRadius: "25px",

  cursor: "pointer",

  fontWeight: "bold"

};



const saveBtn = {

  width: "100%",

  background:

    "linear-gradient(90deg,#2563eb,#7c3aed)",

  color: "white",

  border: "none",

  padding: "15px",

  borderRadius: "15px",

  cursor: "pointer",

  fontSize: "18px",

  fontWeight: "bold",

  marginTop: "20px"

};
